//! Built-in profiles. All are generated by this crate from published colorimetric definitions
//! (primaries, white points, transfer functions) and dedicated to the public domain (CC0-1.0),
//! so documents that embed them carry no licence obligations. See the crate README.

use std::sync::OnceLock;

use crate::Intent;
use crate::curve::{Curve, srgb_trc};
use crate::math::{self, Mat3};
use crate::pipeline::Stage;
use crate::profile::{ColorSpace, Lut, LutKind, Pcs, Profile, ProfileClass};

/// Copyright tag text of every built-in profile.
pub const COPYRIGHT: &str = "No copyright: CC0-1.0 public domain dedication. Generated by photocraft-cms.";

/// Identifiers of the built-in profiles.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Builtin {
    /// sRGB IEC 61966-2.1 (Rec. 709 primaries, D65, sRGB transfer function).
    Srgb,
    /// Display P3 (DCI-P3 primaries, D65, sRGB transfer function).
    DisplayP3,
    /// Adobe RGB (1998)-compatible: its published primaries, D65, gamma 563/256.
    AdobeRgbCompat,
    /// ProPhoto-compatible: ROMM RGB primaries, D50, gamma 1.8.
    ProPhotoCompat,
    /// sRGB primaries with a linear transfer function.
    LinearSrgb,
    /// Rec. 2020 primaries, D65, Rec. 709 transfer function.
    Rec2020,
    /// Gray, gamma 2.2.
    GrayGamma22,
    /// Gray with the sRGB transfer function (sGray): gray `v` looks like RGB `(v, v, v)` in sRGB.
    SGray,
    /// CIE L*a*b* D50 identity (device Lab = PCS Lab, ICC v4 encoding).
    LabD50,
    /// Synthetic coated-offset CMYK (300 % total ink, medium GCR); see [`crate::synth`].
    CoatedCmyk,
    /// Rec. ITU-R BT.709 primaries, D65, pure gamma 2.4 (the BT.1886 display EOTF with a zero black level).
    Rec709Bt1886,
    /// Rec. ITU-R BT.709 primaries, D65, the inverse of the BT.709 camera OETF (scene-referred).
    Rec709Oetf,
    /// P3 primaries, D65, pure gamma 2.6 (SMPTE RP 431-2 transfer on a D65 white).
    P3D65,
    /// DCI-P3: P3 primaries, the DCI white (0.314, 0.351), pure gamma 2.6 (SMPTE RP 431-2).
    DciP3,
    /// Rec. ITU-R BT.2020 primaries, D65, pure gamma 2.4.
    Rec2020G24,
    /// Rec. ITU-R BT.2020 primaries, D65, linear.
    LinearRec2020,
    /// P3 primaries, D65, linear.
    LinearP3D65,
    /// ACEScg (AMPAS S-2014-004): AP1 primaries, the ACES white (≈ D60), linear.
    AcesCg,
}

impl Builtin {
    pub const ALL: [Builtin; 18] = [
        Builtin::Srgb,
        Builtin::DisplayP3,
        Builtin::AdobeRgbCompat,
        Builtin::ProPhotoCompat,
        Builtin::LinearSrgb,
        Builtin::Rec2020,
        Builtin::GrayGamma22,
        Builtin::SGray,
        Builtin::LabD50,
        Builtin::CoatedCmyk,
        Builtin::Rec709Bt1886,
        Builtin::Rec709Oetf,
        Builtin::P3D65,
        Builtin::DciP3,
        Builtin::Rec2020G24,
        Builtin::LinearRec2020,
        Builtin::LinearP3D65,
        Builtin::AcesCg,
    ];

    /// Stable identifier used by commands and settings.
    pub fn id(self) -> &'static str {
        match self {
            Builtin::Srgb => "srgb",
            Builtin::DisplayP3 => "display-p3",
            Builtin::AdobeRgbCompat => "adobe-rgb-compat",
            Builtin::ProPhotoCompat => "prophoto-compat",
            Builtin::LinearSrgb => "linear-srgb",
            Builtin::Rec2020 => "rec2020",
            Builtin::GrayGamma22 => "gray-gamma-2.2",
            Builtin::SGray => "sgray",
            Builtin::LabD50 => "lab-d50",
            Builtin::CoatedCmyk => "coated-cmyk",
            Builtin::Rec709Bt1886 => "rec709-bt1886",
            Builtin::Rec709Oetf => "rec709-oetf",
            Builtin::P3D65 => "p3-d65",
            Builtin::DciP3 => "dci-p3",
            Builtin::Rec2020G24 => "rec2020-g24",
            Builtin::LinearRec2020 => "linear-rec2020",
            Builtin::LinearP3D65 => "linear-p3-d65",
            Builtin::AcesCg => "acescg",
        }
    }

    /// Profile description (the `desc` tag).
    pub fn description(self) -> &'static str {
        match self {
            Builtin::Srgb => "sRGB IEC61966-2.1",
            Builtin::DisplayP3 => "Display P3",
            Builtin::AdobeRgbCompat => "Adobe RGB (1998)-compatible (Photocraft)",
            Builtin::ProPhotoCompat => "ProPhoto RGB-compatible (ROMM primaries, Photocraft)",
            Builtin::LinearSrgb => "Linear sRGB (Photocraft)",
            Builtin::Rec2020 => "Rec. ITU-R BT.2020 (Photocraft)",
            Builtin::GrayGamma22 => "Gray Gamma 2.2 (Photocraft)",
            Builtin::SGray => "sGray (sRGB tone curve, Photocraft)",
            Builtin::LabD50 => "Lab D50 identity (Photocraft)",
            Builtin::CoatedCmyk => crate::synth::DESCRIPTION,
            Builtin::Rec709Bt1886 => "Rec. 709 Gamma 2.4 (BT.1886, Photocraft)",
            Builtin::Rec709Oetf => "Rec. 709 Camera OETF (Photocraft)",
            Builtin::P3D65 => "P3-D65 Gamma 2.6 (Photocraft)",
            Builtin::DciP3 => "DCI-P3 Gamma 2.6 (Photocraft)",
            Builtin::Rec2020G24 => "Rec. 2020 Gamma 2.4 (Photocraft)",
            Builtin::LinearRec2020 => "Linear Rec. 2020 (Photocraft)",
            Builtin::LinearP3D65 => "Linear P3-D65 (Photocraft)",
            Builtin::AcesCg => "ACEScg (AP1 linear, Photocraft)",
        }
    }

    /// Short human-readable name for menus and pickers (English; UIs translate it).
    pub fn label(self) -> &'static str {
        match self {
            Builtin::Srgb => "sRGB",
            Builtin::DisplayP3 => "Display P3",
            Builtin::AdobeRgbCompat => "Adobe RGB (1998) compatible",
            Builtin::ProPhotoCompat => "ProPhoto RGB compatible",
            Builtin::LinearSrgb => "Linear Rec.709/sRGB",
            Builtin::Rec2020 => "Rec.2020",
            Builtin::GrayGamma22 => "Gray Gamma 2.2",
            Builtin::SGray => "sGray",
            Builtin::LabD50 => "Lab D50",
            Builtin::CoatedCmyk => "Coated CMYK",
            Builtin::Rec709Bt1886 => "Rec.709 Gamma 2.4",
            Builtin::Rec709Oetf => "Rec.709 (Camera)",
            Builtin::P3D65 => "P3-D65",
            Builtin::DciP3 => "DCI-P3",
            Builtin::Rec2020G24 => "Rec.2020 Gamma 2.4",
            Builtin::LinearRec2020 => "Linear Rec.2020",
            Builtin::LinearP3D65 => "Linear P3-D65",
            Builtin::AcesCg => "ACEScg",
        }
    }

    /// Does the profile store linear light (an RGB matrix profile with identity curves)?
    pub fn is_linear(self) -> bool {
        matches!(self, Builtin::LinearSrgb | Builtin::LinearRec2020 | Builtin::LinearP3D65 | Builtin::AcesCg)
    }

    /// Looks up an id (case-insensitive; a few aliases and the descriptions are accepted).
    pub fn from_id(s: &str) -> Option<Builtin> {
        let n: String = s.to_ascii_lowercase().chars().filter(|c| c.is_ascii_alphanumeric()).collect();
        let alias = match n.as_str() {
            "srgb" | "srgbiec6196621" | "srgbiec61966" => Some(Builtin::Srgb),
            "p3" | "displayp3" => Some(Builtin::DisplayP3),
            "adobergb" | "adobergb1998" | "adobergbcompat" | "clayrgb" => Some(Builtin::AdobeRgbCompat),
            "prophoto" | "prophotorgb" | "prophotocompat" | "romm" | "rommrgb" => Some(Builtin::ProPhotoCompat),
            "linearsrgb" | "srgblinear" | "linear" => Some(Builtin::LinearSrgb),
            "rec2020" | "bt2020" => Some(Builtin::Rec2020),
            "rec709bt1886" | "bt1886" | "rec709g24" | "rec709gamma24" => Some(Builtin::Rec709Bt1886),
            "rec709oetf" | "rec709camera" | "bt709oetf" => Some(Builtin::Rec709Oetf),
            "p3d65" | "p3d65g26" | "p3d65gamma26" => Some(Builtin::P3D65),
            "dcip3" | "p3dci" => Some(Builtin::DciP3),
            "rec2020g24" | "rec2020gamma24" | "bt2020g24" => Some(Builtin::Rec2020G24),
            "linearrec2020" | "rec2020linear" | "linearbt2020" => Some(Builtin::LinearRec2020),
            "linearp3d65" | "p3d65linear" | "linearp3" => Some(Builtin::LinearP3D65),
            "acescg" | "ap1" | "acescgap1" => Some(Builtin::AcesCg),
            "gray" | "graygamma22" | "gamma22" => Some(Builtin::GrayGamma22),
            "sgray" | "graysrgb" => Some(Builtin::SGray),
            "lab" | "labd50" | "cielab" => Some(Builtin::LabD50),
            "cmyk" | "coatedcmyk" | "defaultcmyk" | "photocraftcoatedcmyk" => Some(Builtin::CoatedCmyk),
            _ => None,
        };
        alias.or_else(|| Builtin::ALL.into_iter().find(|b| b.description().eq_ignore_ascii_case(s)))
    }

    /// The profile (built once per process).
    pub fn profile(self) -> &'static Profile {
        static CELLS: [OnceLock<Profile>; Builtin::ALL.len()] = [const { OnceLock::new() }; Builtin::ALL.len()];
        // `ALL` lists the variants in declaration order (checked by `all_in_declaration_order`),
        // so the discriminant is the cell index.
        CELLS[self as usize].get_or_init(|| build(self))
    }
}

/// The default profile for a colour space: sRGB, sGray, the coated CMYK profile, Lab D50.
pub fn default_for(cs: ColorSpace) -> Option<&'static Profile> {
    Some(match cs {
        ColorSpace::Rgb => Builtin::Srgb.profile(),
        ColorSpace::Gray => Builtin::SGray.profile(),
        ColorSpace::Cmyk => Builtin::CoatedCmyk.profile(),
        ColorSpace::Lab => Builtin::LabD50.profile(),
        _ => return None,
    })
}

pub fn srgb() -> &'static Profile {
    Builtin::Srgb.profile()
}

/// The ICC D65 used for the RGB spaces (chromaticity 0.3127, 0.3290).
fn d65() -> [f64; 3] {
    math::xy_to_xyz(math::D65_XY)
}

/// Colorant matrix adapted to D50 and quantized to s15Fixed16, with each row nudged so that
/// RGB (1, 1, 1) maps exactly to the stored D50 white (keeps neutrals neutral).
fn colorants(r: [f64; 2], g: [f64; 2], b: [f64; 2], white: [f64; 3]) -> (Mat3, Option<Mat3>) {
    // Only called with the constant primaries of the built-in spaces, which are independent
    // (every built-in profile is built in the tests).
    #[allow(clippy::expect_used)]
    let m = math::rgb_to_xyz_matrix(r, g, b, white).expect("built-in primaries are independent");
    let d50 = math::d50_quantized();
    let adapt = if (white[0] - math::D50[0]).abs() < 1e-3 && (white[2] - math::D50[2]).abs() < 1e-3 { None } else { Some(math::bradford(white, math::D50)) };
    let m50 = match &adapt {
        Some(a) => math::mul(a, &m),
        None => {
            // White already (nearly) D50: scale rows onto the exact PCS white.
            let s = math::apply(&m, [1.0, 1.0, 1.0]);
            let mut o = m;
            for (i, row) in o.iter_mut().enumerate() {
                for v in row.iter_mut() {
                    *v *= math::D50[i] / s[i];
                }
            }
            o
        }
    };
    let mut q = m50.map(|row| row.map(math::s15f16_round));
    for (i, row) in q.iter_mut().enumerate() {
        let err = d50[i] - row.iter().sum::<f64>();
        let k = (0..3).max_by(|a, b| row[*a].abs().total_cmp(&row[*b].abs())).unwrap_or(0);
        row[k] = math::s15f16_round(row[k] + err);
    }
    (q, adapt.map(|a| a.map(|row| row.map(math::s15f16_round))))
}

fn rgb(desc: &str, prim: [[f64; 2]; 3], white: [f64; 3], trc: Curve) -> Profile {
    let (m, chad) = colorants(prim[0], prim[1], prim[2], white);
    Profile {
        version: (4, 0x30),
        class: ProfileClass::Display,
        color_space: ColorSpace::Rgb,
        pcs: Pcs::Xyz,
        rendering_intent: Intent::Perceptual,
        description: desc.into(),
        copyright: COPYRIGHT.into(),
        white_point: math::d50_quantized(),
        black_point: None,
        chad,
        matrix: Some(m),
        trc: Some([trc.clone(), trc.clone(), trc]),
        gray_trc: None,
        a2b: [None, None, None],
        b2a: [None, None, None],
        bytes: None,
        hash: Default::default(),
    }
    .with_encoded_bytes()
}

fn gray(desc: &str, trc: Curve) -> Profile {
    Profile {
        version: (4, 0x30),
        class: ProfileClass::Display,
        color_space: ColorSpace::Gray,
        pcs: Pcs::Xyz,
        rendering_intent: Intent::Perceptual,
        description: desc.into(),
        copyright: COPYRIGHT.into(),
        white_point: math::d50_quantized(),
        black_point: None,
        chad: None,
        matrix: None,
        trc: None,
        gray_trc: Some(trc),
        a2b: [None, None, None],
        b2a: [None, None, None],
        bytes: None,
        hash: Default::default(),
    }
    .with_encoded_bytes()
}

fn lab() -> Profile {
    let ident = || Lut { kind: LutKind::Ab, inputs: 3, outputs: 3, stages: vec![Stage::Curves(vec![Curve::Identity; 3])] };
    Profile {
        version: (4, 0x30),
        class: ProfileClass::ColorSpace,
        color_space: ColorSpace::Lab,
        pcs: Pcs::Lab,
        rendering_intent: Intent::Perceptual,
        description: Builtin::LabD50.description().into(),
        copyright: COPYRIGHT.into(),
        white_point: math::d50_quantized(),
        black_point: None,
        chad: None,
        matrix: None,
        trc: None,
        gray_trc: None,
        a2b: [Some(ident()), None, None],
        b2a: [Some(ident()), None, None],
        bytes: None,
        hash: Default::default(),
    }
    .with_encoded_bytes()
}

/// The shipped synthetic CMYK profile (generated by [`crate::synth::coated_cmyk`]; regenerate
/// with `PHOTOCRAFT_REGEN_PROFILES=1 cargo test -p photocraft-cms --release regen`).
pub const COATED_CMYK_ICC: &[u8] = include_bytes!("../profiles/photocraft-coated-cmyk.icc");

fn build(b: Builtin) -> Profile {
    let (srgb_p, p3, adobe, romm, bt2020) = (
        [[0.64, 0.33], [0.30, 0.60], [0.15, 0.06]],
        [[0.680, 0.320], [0.265, 0.690], [0.150, 0.060]],
        [[0.64, 0.33], [0.21, 0.71], [0.15, 0.06]],
        [[0.7347, 0.2653], [0.1596, 0.8404], [0.0366, 0.0001]],
        [[0.708, 0.292], [0.170, 0.797], [0.131, 0.046]],
    );
    // Rec. 709 OETF inverse: V = 1.099 L^0.45 − 0.099 (L ≥ 0.018), 4.5 L below.
    let bt709_trc = || {
        let a = 1.099;
        Curve::Parametric { kind: 3, p: [1.0 / 0.45, 1.0 / a, (a - 1.0) / a, 1.0 / 4.5, 0.081, 0.0, 0.0] }
    };
    // ACES AP1 primaries and white (AMPAS S-2014-004).
    let ap1 = [[0.713, 0.293], [0.165, 0.830], [0.128, 0.044]];
    let aces_white = math::xy_to_xyz([0.32168, 0.33767]);
    let dci_white = math::xy_to_xyz([0.314, 0.351]);
    match b {
        Builtin::Srgb => rgb(b.description(), srgb_p, d65(), srgb_trc()),
        Builtin::DisplayP3 => rgb(b.description(), p3, d65(), srgb_trc()),
        Builtin::AdobeRgbCompat => rgb(b.description(), adobe, d65(), Curve::Gamma(563.0 / 256.0)),
        Builtin::ProPhotoCompat => rgb(b.description(), romm, math::D50, Curve::Gamma(1.8)),
        Builtin::LinearSrgb => rgb(b.description(), srgb_p, d65(), Curve::Gamma(1.0)),
        Builtin::Rec2020 => rgb(b.description(), bt2020, d65(), bt709_trc()),
        Builtin::Rec709Bt1886 => rgb(b.description(), srgb_p, d65(), Curve::Gamma(2.4)),
        Builtin::Rec709Oetf => rgb(b.description(), srgb_p, d65(), bt709_trc()),
        Builtin::P3D65 => rgb(b.description(), p3, d65(), Curve::Gamma(2.6)),
        Builtin::DciP3 => rgb(b.description(), p3, dci_white, Curve::Gamma(2.6)),
        Builtin::Rec2020G24 => rgb(b.description(), bt2020, d65(), Curve::Gamma(2.4)),
        Builtin::LinearRec2020 => rgb(b.description(), bt2020, d65(), Curve::Gamma(1.0)),
        Builtin::LinearP3D65 => rgb(b.description(), p3, d65(), Curve::Gamma(1.0)),
        Builtin::AcesCg => rgb(b.description(), ap1, aces_white, Curve::Gamma(1.0)),
        Builtin::GrayGamma22 => gray(b.description(), Curve::Gamma(2.2)),
        Builtin::SGray => gray(b.description(), srgb_trc()),
        Builtin::LabD50 => lab(),
        // The shipped bytes are `synth::coated_cmyk()` (checked by the `regen` test); rebuild
        // them rather than crash if they ever fail to parse.
        Builtin::CoatedCmyk => Profile::parse(COATED_CMYK_ICC).unwrap_or_else(|_| crate::synth::coated_cmyk()),
    }
}
